-- Field diagnostics for delivery through a teammate (docs/nearby-sync-plan.md
-- section 6, phase 4): a `nearby` record with `event` `deliver` when a sync
-- delivered teammates' signed work, with how many events it sent, how many the
-- server took as new, how many were refused here (of them stamped too far
-- ahead, and a revoked key's later work or past its cap), how many batches the
-- relay did not try and how many it answered, and the class of what stopped it
-- early. Counts and codes only: no author, key, event or file. Only the
-- `event` value is new; every field was already allowed.

-- The twin of DIAG_SCHEMA, NEARBY_DIAG_SCHEMA and DIAG_CONTEXT in
-- packages/sync/src/diagnostics.ts and nearbyDiag.ts; scripts/diagSchema.test.ts
-- holds them equal. Change both together.
create or replace function diag.schema() returns jsonb language sql immutable as $$
select
-- diag-schema:begin
'{"kinds":{"sync":{"n":["ms","pushNetMs","pullNetMs","applyMs","pushed","rejected","pulled","pages","pending","offlineMs","rejNotMember","rejNotAllowed","rejNotListed","rejInvalid","rejClockAhead","rejOther","requeued","more"],"t":{"outcome":["ok","offline","unrenewed","refused","too_old","error"],"error":"token","code":"token","phase":["push","pull","snapshot","checkpoint","load","store"]}},"load":{"n":["ms","events","fromSnapshot","staleCheckpointSeq","readMs","foldMs"],"t":{"reason":["open","rejected","requeue","redaction","snapshot","membership","other"],"checkpoint":["none","ok","old_reducer"]}},"checkpoint":{"n":["ms","kb","seq","pruned"],"t":{"path":["fast","slow"]}},"open":{"n":["ms","syncs","pulled","snapshotMs","loadMs"],"t":{"cold":["yes","no"]}},"snapshot":{"n":["ms","chunks","resumedChunks","bytes","seq"],"t":{"outcome":["ok","none","stale"],"why":["cold","redaction","reducer"]}},"fill":{"n":["ms","msToMap","headKb","passages","rows"],"t":{"event":["start","done","fallback","restart"],"why":["cold","redaction","reducer"],"reason":["no_rpc","no_cut","no_lines","old_lines","error","cut_gone"]}},"transfer":{"n":["count","bytes","ms","maxMs","signMs","fetchMs","verifyMs","failOffline","failHttp4xx","failHttp5xx","failHash","failDisk","failOther","failAuth","failNotFound","failTooLarge","failBadDigest","failGone"],"t":{"dir":["up","down"],"src":["lang","guide","handover","stream","source","help","study"]}},"device":{"n":["freeDiskMb","totalDiskMb","blobCacheMb","blobsWanted","lostFiles","lostRecordings","journalPending","journalFailed","uploadsWaiting","oldestUnsentMin","wantedStuckMin","streams","localEvents","dbMb","diagQueued","diagDropped"],"t":{}},"error":{"n":[],"t":{"name":"token","where":"token","errorId":"token","fatal":["yes","no"],"code":"token"}},"expected":{"n":["count"],"t":{"where":"token","name":"token","code":"token"}},"audio":{"n":["takes","takeMs","tooShort","micRefused","startFail","stopFail","saveFail","encodeFail","wavKept","interrupted","plays","playFail","playNotHere","streamFail","waits","waitMs","maxWaitMs"],"t":{}},"auth":{"n":["ms","status","attempt","ageH","pending","eventsLeft","uploadsLeft","accountLeft","sinceOkMs"],"t":{"op":["sign_in","sign_up","code","v2","redeem","join","renew","ended","courier","outbox","route","delete","org_list"],"outcome":["ok","offline","http","refused","rate_limited","server","expired","used","not_found","retired","needs_name","done","keep","gone","unreachable","retry","failed","home","no_org","org_unknown"],"code":"token","action":"token"}},"nearby":{"n":["ms","levelMs","heard","echoed","maybe","taps","maxUnmatched","pipeFails","strangers","busy","noAnswer","sessions","done","fallbacks","events","sent","refused","overBudget","files","served","fileFails","keyRefused","farAhead","noRoom","cutBackups","older","clockOff","newerApp"],"t":{"event":["room","session","find","blocked","deliver"],"stop":["asked","idle","wait","run","level","no-key"],"role":["i","r"],"end":["done","silent","no-answer","said","heard","dropped","stalled","failed"],"bye":["done","nothing","busy","protocol","identity","not-member","stopped"],"link":["wifi-direct","hotspot","bluetooth"],"code":["NOT_AVAILABLE","NO_PERMISSION","BLUETOOTH_OFF","WIFI_OFF","BAD_ARGUMENT","ADVERTISE_UNSUPPORTED","ADVERTISE_FAILED","SCAN_FAILED","FIND_NOT_RUNNING","PEER_GONE","PIPE_FAILED","PIPE_TIMEOUT","P2P_UNSUPPORTED","GROUP_BUSY","GROUP_FAILED","HOTSPOT_NO_CHANNEL","HOTSPOT_INCOMPATIBLE","HOTSPOT_TETHERING_DISALLOWED","HOTSPOT_FAILED","JOIN_FAILED","JOIN_TIMEOUT","HOST_TAKEN_DOWN","LINK_UNKNOWN","LINK_CLOSED","LINK_DROPPED","TAG_FAILED","FRAME_TOO_LARGE","MESSAGE_TOO_LARGE","NOT_SECURED","ALREADY_SECURED","OPENING_AFTER_SECURE","TRANSFER_BUSY","FILE_TOO_BIG","FILE_NO_SPACE","FILE_REFUSED","FILE_CANCELLED","FILE_UNREADABLE","FILE_WRITE_FAILED","FILE_SIZE_MISMATCH","STAGING_REFUSED","STOPPED","INTERNAL"],"error":"token","why":["not-in-build","android-too-old","no-bluetooth-le","no-wifi-direct","no-key","no-certificate","read-only","bluetooth-off","wifi-off","location-off","permission-approximate","permission-blocked"],"adv":["yes","no"],"direct":["yes","no"],"hotspot":["yes","no"]}}},"context":["installId","os","osVersion","model","appVersion","runtimeVersion","updateId","channel","embedded","reducerVersion","protocolVersion"]}'
-- diag-schema:end
::jsonb
$$;

-- Unchanged; restated so the newest migration holding the schema holds its
-- token pattern too (scripts/diagSchema.test.ts reads both from one file).
create or replace function diag.is_token(p text) returns boolean language sql immutable as $$
  select p is not null and p ~ '^[A-Za-z0-9 _.:()/#-]{1,80}$'
$$;
